insert into public.dialogues (key, speaker_external_id, source_path, source_metadata) select key, speaker_external_id, source_path, source_metadata from jsonb_to_recordset($seed$[{"key":"nouns_blacksmith_equipment_restored","speaker_external_id":"Blacksmith","source_path":"_registry\\dialogues\\kingdom_nouns.yaml","source_metadata":{}},{"key":"nouns_blacksmith_mixed_equipment","speaker_external_id":"Blacksmith","source_path":"_registry\\dialogues\\kingdom_nouns.yaml","source_metadata":{}},{"key":"nouns_cannoneer_names_restored","speaker_external_id":"Cannoneer","source_path":"_registry\\dialogues\\kingdom_nouns.yaml","source_metadata":{}},{"key":"nouns_cannoneer_wrong_names","speaker_external_id":"Cannoneer","source_path":"_registry\\dialogues\\kingdom_nouns.yaml","source_metadata":{}},{"key":"nouns_fenn_mixed_places","speaker_external_id":"City Gaurd Info","source_path":"_registry\\dialogues\\kingdom_nouns.yaml","source_metadata":{}},{"key":"nouns_fenn_places_restored","speaker_external_id":"City Gaurd Info","source_path":"_registry\\dialogues\\kingdom_nouns.yaml","source_metadata":{}},{"key":"nouns_maya_book_restored","speaker_external_id":"teacher_maya","source_path":"_registry\\dialogues\\kingdom_nouns.yaml","source_metadata":{}},{"key":"nouns_maya_final_trial","speaker_external_id":"teacher_maya","source_path":"_registry\\dialogues\\kingdom_nouns.yaml","source_metadata":{}},{"key":"nouns_maya_missing_roles","speaker_external_id":"teacher_maya","source_path":"_registry\\dialogues\\kingdom_nouns.yaml","source_metadata":{}},{"key":"nouns_maya_roles_restored","speaker_external_id":"teacher_maya","source_path":"_registry\\dialogues\\kingdom_nouns.yaml","source_metadata":{}},{"key":"nouns_old_woman_new_roles","speaker_external_id":"Old Woman","source_path":"_registry\\dialogues\\kingdom_nouns.yaml","source_metadata":{}},{"key":"nouns_old_woman_roles_restored","speaker_external_id":"Old Woman","source_path":"_registry\\dialogues\\kingdom_nouns.yaml","source_metadata":{}},{"key":"nouns_professor_crown_soup","speaker_external_id":"Professor Crazy","source_path":"_registry\\dialogues\\kingdom_nouns.yaml","source_metadata":{}},{"key":"nouns_professor_treasury_restored","speaker_external_id":"Professor Crazy","source_path":"_registry\\dialogues\\kingdom_nouns.yaml","source_metadata":{}}]$seed$::jsonb) as entries(key text, speaker_external_id text, source_path text, source_metadata jsonb) on conflict (key) do update set speaker_external_id = excluded.speaker_external_id, source_path = excluded.source_path, source_metadata = excluded.source_metadata, updated_at = now();
insert into public.dialogue_lines (dialogue_id, locale, line_order, content, line_format) select dialogues.id, lines.locale, lines.line_order, lines.content, lines.line_format from jsonb_to_recordset($seed$[{"dialogue_key":"nouns_blacksmith_equipment_restored","locale":"he","line_order":0,"content":"עבודה טובה: <strong>sword</strong> (חרב), <strong>shield</strong> (מגן), <strong>scroll</strong> (מגילה).","line_format":"safe_rich_text"},{"dialogue_key":"nouns_blacksmith_equipment_restored","locale":"he","line_order":1,"content":"המגן שוב מגן, החרב חזרה למעמד, והמגילה ניצלה מן המרק.","line_format":"plain_text"},{"dialogue_key":"nouns_blacksmith_equipment_restored","locale":"he","line_order":2,"content":"מישהו במטבח התאכזב — לדבריו המגן היה המגש המרשים ביותר. תודה על ה־Power Stone.","line_format":"plain_text"},{"dialogue_key":"nouns_blacksmith_mixed_equipment","locale":"he","line_order":0,"content":"בלגן בנשקייה! המגן משמש כמגש מרק, מנסים לכתוב בעזרת חרב, ומנגבים את השולחן במגילה.","line_format":"plain_text"},{"dialogue_key":"nouns_blacksmith_mixed_equipment","locale":"he","line_order":1,"content":"שלושת השמות באנגלית: חרב היא <strong>sword</strong>, מגן הוא <strong>shield</strong>, ומגילה היא <strong>scroll</strong>.","line_format":"safe_rich_text"},{"dialogue_key":"nouns_blacksmith_mixed_equipment","locale":"he","line_order":2,"content":"אייתו את המילה מגן באנגלית על גשר אבן השבועה, ואז אמרו בקול: חרב, מגן ומגילה.","line_format":"plain_text"},{"dialogue_key":"nouns_cannoneer_names_restored","locale":"he","line_order":0,"content":"כך טוב יותר: <strong>dragon</strong> (דרקון), <strong>griffin</strong> (גריפין), <strong>goblin</strong> (גובלין).","line_format":"safe_rich_text"},{"dialogue_key":"nouns_cannoneer_names_restored","locale":"he","line_order":1,"content":"הגובלין החזיר את כרטיס הדרקון, אבל הוא עדיין מבקש אוצר קטן 'רק לניסיון'.","line_format":"plain_text"},{"dialogue_key":"nouns_cannoneer_names_restored","locale":"he","line_order":2,"content":"תודה על ה־Ancient Rune. בום! עכשיו כולם עם השם הנכון.","line_format":"plain_text"},{"dialogue_key":"nouns_cannoneer_wrong_names","locale":"he","line_order":0,"content":"עלבון נורא במפרץ! מישהו הצמיד לדרקון את הכרטיס של גובלין. הוא דרקון מכובד, לא גובלין קטן!","line_format":"plain_text"},{"dialogue_key":"nouns_cannoneer_wrong_names","locale":"he","line_order":1,"content":"הגובלין קיבל את כרטיס הדרקון וכבר דורש טירה ואוצר. הגריפין קיבל שם שגוי ומנסה לנשוף אש.","line_format":"plain_text"},{"dialogue_key":"nouns_cannoneer_wrong_names","locale":"he","line_order":2,"content":"אייתו את המילה דרקון באנגלית במפרץ הנטוש, ואז אמרו בקול: דרקון, גריפין וגובלין.","line_format":"plain_text"},{"dialogue_key":"nouns_fenn_mixed_places","locale":"he","line_order":0,"content":"המפה ליד השער השתגעה: הטירה מסומנת כמגדל, המגדל כשער, והשער כטירה.","line_format":"plain_text"},{"dialogue_key":"nouns_fenn_mixed_places","locale":"he","line_order":1,"content":"נלמד שלושה שמות מקומות באנגלית: טירה היא <strong>castle</strong>, מגדל הוא <strong>tower</strong>, ושער הוא <strong>gate</strong>.","line_format":"safe_rich_text"},{"dialogue_key":"nouns_fenn_mixed_places","locale":"he","line_order":2,"content":"אייתו את המילה טירה באנגלית ליד שער הממלכה, ואז אמרו בקול: טירה, מגדל ושער.","line_format":"plain_text"},{"dialogue_key":"nouns_fenn_places_restored","locale":"he","line_order":0,"content":"המפה שוב נכונה: <strong>castle</strong> (טירה), <strong>tower</strong> (מגדל), <strong>gate</strong> (שער).","line_format":"safe_rich_text"},{"dialogue_key":"nouns_fenn_places_restored","locale":"he","line_order":1,"content":"השומרים שכבר טיפסו למגדל במקום להגיע לשער מבקשים שנציב שם דלת. הבקשה עדיין בבדיקה.","line_format":"plain_text"},{"dialogue_key":"nouns_fenn_places_restored","locale":"he","line_order":2,"content":"תודה על ה־Gem. תעבירו למאיה שהמפה שוב בסדר — אני כבר סיפרתי לכל העיר.","line_format":"plain_text"},{"dialogue_key":"nouns_maya_book_restored","locale":"he","line_order":0,"content":"הצלחתם! ספר השמות של הממלכה שלם, וכל מילה חזרה למקום הנכון.","line_format":"plain_text"},{"dialogue_key":"nouns_maya_book_restored","locale":"he","line_order":1,"content":"אתם קוראים ואומרים באנגלית שמות של אנשים, מקומות, חפצים ויצורים מן הממלכה.","line_format":"plain_text"},{"dialogue_key":"nouns_maya_book_restored","locale":"he","line_order":2,"content":"פרופסור משוגע ביקש את הכתר. הזקנה שוב הביאה קערת מרק — הפעם בכוונה. אפילו התותחן צחק.","line_format":"plain_text"},{"dialogue_key":"nouns_maya_book_restored","locale":"he","line_order":3,"content":"קבלו את ה־Ancient Rune ואת מטבעות הסיום. אתם שומרי השמות של הממלכה.","line_format":"plain_text"},{"dialogue_key":"nouns_maya_final_trial","locale":"he","line_order":0,"content":"כל דפי הספר נמצאו, אבל הספר ייסגר שוב אם המילים לא באמת נלמדו. הגיע מבחן השמות של הממלכה.","line_format":"plain_text"},{"dialogue_key":"nouns_maya_final_trial","locale":"he","line_order":1,"content":"סדרו באנגלית את הכתיב של כמה מילים מוכרות (מלכה, טירה, כיסא־מלכות, מגן, דרקון), ואז אמרו בקול מילה אחת מכל קבוצה.","line_format":"plain_text"},{"dialogue_key":"nouns_maya_final_trial","locale":"he","line_order":2,"content":"לא נוסיף מילים חדשות. זה הזמן לזכור את האנשים, המקומות, החפצים והיצורים שכבר פגשנו.","line_format":"plain_text"},{"dialogue_key":"nouns_maya_missing_roles","locale":"he","line_order":0,"content":"אסון בספר השמות! שלוש מילים ברחו מן הפרק על אנשי הארמון: מלך, מלכה ואביר.","line_format":"plain_text"},{"dialogue_key":"nouns_maya_missing_roles","locale":"he","line_order":1,"content":"בלי השמות האלה באנגלית, המלך לא יודע שהוא <strong>king</strong>, המלכה מחפשת את הכרטיס <strong>queen</strong>, והאביר כבר התיישב על הכיסא של המלך.","line_format":"safe_rich_text"},{"dialogue_key":"nouns_maya_missing_roles","locale":"he","line_order":2,"content":"אייתו את המילה מלך באנגלית ליד מזרקת הכסף, ואז אמרו בקול: מלך, מלכה ואביר.","line_format":"plain_text"},{"dialogue_key":"nouns_maya_roles_restored","locale":"he","line_order":0,"content":"מצוין: <strong>king</strong> (מלך), <strong>queen</strong> (מלכה), <strong>knight</strong> (אביר).","line_format":"safe_rich_text"},{"dialogue_key":"nouns_maya_roles_restored","locale":"he","line_order":1,"content":"האביר ירד מן הכס, אבל ביקש לקחת איתו את הכרית. לדבריו, גם אביר ראוי לשבת בנוחות.","line_format":"plain_text"},{"dialogue_key":"nouns_maya_roles_restored","locale":"he","line_order":2,"content":"תודה על ה־Gem. המילים האלה יחזרו שוב בהמשך.","line_format":"plain_text"},{"dialogue_key":"nouns_old_woman_new_roles","locale":"he","line_order":0,"content":"ברוכים הבאים למטבח! לפחות נדמה לי שאני הטבחית... איבדנו את שמות הקוסם, הטבח והשומר.","line_format":"plain_text"},{"dialogue_key":"nouns_old_woman_new_roles","locale":"he","line_order":1,"content":"הקוסם מערבב מרק עם שרביט, הטבח שומר על השער בעזרת כף, והשומר מנופף במקל וצועק 'קסם!'.","line_format":"plain_text"},{"dialogue_key":"nouns_old_woman_new_roles","locale":"he","line_order":2,"content":"אייתו את המילה קוסם באנגלית במגדל המשמר האבוד, ואז אמרו בקול: קוסם, טבח ושומר — לפני שהמרק מתחיל לעוף.","line_format":"plain_text"},{"dialogue_key":"nouns_old_woman_roles_restored","locale":"he","line_order":0,"content":"נזכרתי! אני מגישה חטיפים, לא מערבבת קסמים. בקסם עובד <strong>wizard</strong> (קוסם), במטבח <strong>cook</strong> (טבח), וליד השער <strong>guard</strong> (שומר).","line_format":"safe_rich_text"},{"dialogue_key":"nouns_old_woman_roles_restored","locale":"he","line_order":1,"content":"השומר הפסיק לנסות קסמים. זה לטובה — בפעם האחרונה הוא הפך את הקסדה שלו לקומקום.","line_format":"plain_text"},{"dialogue_key":"nouns_old_woman_roles_restored","locale":"he","line_order":2,"content":"תודה על ה־Power Stone. קחו גם עוגייה — בלי קסם הפעם.","line_format":"plain_text"},{"dialogue_key":"nouns_professor_crown_soup","locale":"he","line_order":0,"content":"סוף סוף הגעתם! בניסוי שלי איבדתי שלושה שמות חשובים: כתר, כיסא־מלכות ואוצר.","line_format":"plain_text"},{"dialogue_key":"nouns_professor_crown_soup","locale":"he","line_order":1,"content":"כתר הוא <strong>crown</strong>, כיסא־מלכות הוא <strong>throne</strong>, ואוצר הוא <strong>treasure</strong>. שמתי קערת מרק על הראש וישבתי על תיבת האוצר — למען המדע!","line_format":"safe_rich_text"},{"dialogue_key":"nouns_professor_crown_soup","locale":"he","line_order":2,"content":"אייתו את המילה כתר באנגלית במגדל הבדידות, ואז אמרו בקול: כתר, כיסא־מלכות ואוצר.","line_format":"plain_text"},{"dialogue_key":"nouns_professor_treasury_restored","locale":"he","line_order":0,"content":"נפלא: <strong>crown</strong> (כתר) על הראש, <strong>throne</strong> (כיסא־מלכות) באולם, ו־<strong>treasure</strong> (אוצר) בכספת.","line_format":"safe_rich_text"},{"dialogue_key":"nouns_professor_treasury_restored","locale":"he","line_order":1,"content":"קערת המרק חזרה למטבח. היא הייתה קלה יותר מן הכתר, אבל הרבה פחות מלכותית.","line_format":"plain_text"},{"dialogue_key":"nouns_professor_treasury_restored","locale":"he","line_order":2,"content":"תודה על ה־Power Stone. הניסוי נכשל בהצלחה מסחררת.","line_format":"plain_text"}]$seed$::jsonb) as lines(dialogue_key text, locale text, line_order integer, content text, line_format text) join public.dialogues on dialogues.key = lines.dialogue_key on conflict (dialogue_id, locale, line_order) do update set content = excluded.content, line_format = excluded.line_format;
